def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()

        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1).strip()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            if not local:
                return ""

        return local + "@" + domain

    def normalize_phone(value):
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value[:5]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value.strip(), fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for index, row in enumerate(rows):
        item = {
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
        }

        # Rows without either valid contact method cannot participate in matching.
        if item["email"] or item["phone"]:
            normalized.append(item)

    # Union-find for transitive matching.
    parent = list(range(len(normalized)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_last_owner = {}

    for i, item in enumerate(normalized):
        if item["email"]:
            previous = email_owner.get(item["email"])
            if previous is None:
                email_owner[item["email"]] = i
            else:
                union(i, previous)

        if item["phone"] and item["last_name"]:
            key = (item["phone"], item["last_name"].casefold())
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, item in enumerate(normalized):
        groups.setdefault(find(i), []).append(item)

    def choose_field(group, field):
        candidates = [item for item in group if item[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda item: (
                item["source"] == "manual",
                item["updated_dt"],
                -item["index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        latest = max(item["updated_dt"] for item in group)
        tags = set().union(*(item["tags"] for item in group))

        output.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(item["opted_out"] for item in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
            "_earliest_index": min(item["index"] for item in group),
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
